firmware:
const int TRIG = 5;
const int ECHO = 18;
const int BUZZ = 13;

long readCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  return us / 58;
}

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZ, OUTPUT);
}

void loop() {
  long cm = readCm();
  if (cm > 0 && cm < 30) {
    digitalWrite(BUZZ, HIGH);
    Serial.println("NEAR");
  } else {
    digitalWrite(BUZZ, LOW);
    Serial.println("FAR");
  }
  delay(300);
}
